import { Field } from '@/components/ui/field';
import { Fieldset } from '@/components/ui/fieldset';
import { Input } from '@/components/ui/input';

<Fieldset.Root>
  <Fieldset.Legend>Account</Fieldset.Legend>
  <Field.Root name="email">
    <Field.Label>Email</Field.Label>
    <Input type="email" />
  </Field.Root>
</Fieldset.Root>

import { InputOTP } from '@/components/ui/input-otp';

<label htmlFor="code">Verification code</label>
<InputOTP.Root id="code" length={6}>
  {Array.from({ length: 6 }, (_, index) => (
    <InputOTP.Input key={index} aria-label={index === 0 ? undefined : `Character ${index + 1} of 6`} />
  ))}
</InputOTP.Root>

length is required; the consumer renders one Input per slot. size sits on Root and reaches the slots through context. Slots two through N take their own aria-label because the first slot is named by the field's label.

